package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="vehicles") public class Vehicle { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="vehicle_number") private String vehicleNumber; @Column(name="vehicle_type") private String vehicleType; @Column(name="capacity_kg") private BigDecimal capacityKg; @Enumerated(EnumType.STRING) private Statuses.VehicleStatus status=Statuses.VehicleStatus.AVAILABLE; public Long getId(){return id;} public String getVehicleNumber(){return vehicleNumber;} public void setVehicleNumber(String v){vehicleNumber=v;} public String getVehicleType(){return vehicleType;} public void setVehicleType(String v){vehicleType=v;} public BigDecimal getCapacityKg(){return capacityKg;} public void setCapacityKg(BigDecimal v){capacityKg=v;} public Statuses.VehicleStatus getStatus(){return status;} public void setStatus(Statuses.VehicleStatus v){status=v;} }
